-- MICHELIN Key hotels, France 2026 (prepared 2026-10-29 export, written 2026-10-30).
-- Adds every French MICHELIN Key hotel missing from `hotels`, gives every French Key hotel
-- its current 2026 Key row, fills empty contact fields on existing ones (fill-only), and
-- links French starred restaurants to Key hotels where MICHELIN's restaurant page says
-- "Stay at the hotel". Generated by build_fr_key_hotels.py; evidence in
-- fr_key_hotels_2026.csv and match_report.csv, decisions in README.md.
--
-- Prerequisite: supabase/migrations/20261023190000_add_fr_key_hotel_cities.sql (new towns).
-- One transaction; every check raises and rolls the whole file back.
-- Run: supabase db query --linked -f <absolute path to this file>

begin;

do $$
declare n int;
begin
  select count(*) into n from public.hotels where country_code = 'FR';
  if n <> 10 then raise exception 'FR: expected 10 hotels (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('hotel_707', 'Cheval Blanc Paris'), ('hotel_708', 'Hôtel de Crillon'), ('hotel_709', 'Hôtel du Cap-Eden-Roc'), ('hotel_710', 'Hôtel du Couvent'), ('hotel_711', 'La Réserve Paris'), ('hotel_712', 'Le Bristol Paris'), ('hotel_713', 'Plaza Athénée'), ('hotel_714', 'The Maybourne Riviera'), ('hotel_791', 'Ritz Paris'), ('hotel_793', 'Carlton Cannes')) e(code, name)
   where not exists (select 1 from public.hotels h where h.hotel_code = e.code and h.name = e.name and h.country_code = 'FR');
  if n <> 0 then raise exception 'FR: % exported hotel codes no longer carry their exported name', n; end if;
  select count(*) into n from public.restaurants where country_code = 'FR';
  if n <> 653 then raise exception 'FR: expected 653 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from public.hotel_restaurants hr join public.restaurants r on r.id = hr.restaurant_id where r.country_code = 'FR';
  if n <> 5 then raise exception 'FR: expected 5 restaurant hotel links (export), found %', n; end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 2001 and 2211) then
    raise exception 'hotel codes hotel_2001..hotel_2211 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

-- 1. French MICHELIN Key hotels missing from `hotels` (211)
create temp table _new_hotels_fr (code text, name text, keys smallint, city text, address text, lon float8, lat float8,
                               michelin_url text, website_url text, phone text) on commit drop;
do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_fr x
   where (select count(*) from public.cities c where c.country_code = 'FR' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one FR row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_fr x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'FR' and c.name = x.city), 'FR',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_fr x;

-- 1c. current 2026 Key row for every French Key hotel that lacks one (the new rows above, and
--     existing FR hotels the August World's 50 Best import left without one; PE_REPORT finding 1)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_2001', 'hotel_2002', 'hotel_2003', 'hotel_2004', 'hotel_2005', 'hotel_707', 'hotel_2006', 'hotel_2007', 'hotel_2008', 'hotel_2009', 'hotel_709', 'hotel_2010', 'hotel_711', 'hotel_2011', 'hotel_712', 'hotel_2012', 'hotel_2013', 'hotel_2014', 'hotel_713', 'hotel_2015', 'hotel_2016', 'hotel_791', 'hotel_2017', 'hotel_2018', 'hotel_2019', 'hotel_2020', 'hotel_2021', 'hotel_2022', 'hotel_2023', 'hotel_2024', 'hotel_2025', 'hotel_2026', 'hotel_2027', 'hotel_2028', 'hotel_2029', 'hotel_2030', 'hotel_2031', 'hotel_2032', 'hotel_2033', 'hotel_708', 'hotel_2034', 'hotel_2035', 'hotel_2036', 'hotel_2037', 'hotel_2038', 'hotel_2039', 'hotel_2040', 'hotel_2041', 'hotel_2042', 'hotel_2043', 'hotel_2044', 'hotel_2045', 'hotel_2046', 'hotel_2047', 'hotel_2048', 'hotel_2049', 'hotel_2050', 'hotel_2051', 'hotel_2052', 'hotel_2053', 'hotel_714', 'hotel_2054', 'hotel_2055', 'hotel_2056', 'hotel_2057', 'hotel_2058', 'hotel_2059', 'hotel_2060', 'hotel_2061', 'hotel_2062', 'hotel_2063', 'hotel_2064', 'hotel_2065', 'hotel_2066', 'hotel_2067', 'hotel_2068', 'hotel_2069', 'hotel_2070', 'hotel_2071', 'hotel_2072', 'hotel_2073', 'hotel_2074', 'hotel_2075', 'hotel_2076', 'hotel_2077', 'hotel_2078', 'hotel_2079', 'hotel_2080', 'hotel_2081', 'hotel_2082', 'hotel_2083', 'hotel_2084', 'hotel_2085', 'hotel_2086', 'hotel_2087', 'hotel_2088', 'hotel_2089', 'hotel_2090', 'hotel_2091', 'hotel_2092', 'hotel_2093', 'hotel_2094', 'hotel_2095', 'hotel_2096', 'hotel_2097', 'hotel_2098', 'hotel_2099', 'hotel_2100', 'hotel_2101', 'hotel_2102', 'hotel_2103', 'hotel_2104', 'hotel_2105', 'hotel_2106', 'hotel_2107', 'hotel_2108', 'hotel_2109', 'hotel_2110', 'hotel_2111', 'hotel_2112', 'hotel_2113', 'hotel_2114', 'hotel_2115', 'hotel_2116', 'hotel_2117', 'hotel_2118', 'hotel_2119', 'hotel_710', 'hotel_2120', 'hotel_2121', 'hotel_2122', 'hotel_2123', 'hotel_2124', 'hotel_2125', 'hotel_2126', 'hotel_2127', 'hotel_2128', 'hotel_2129', 'hotel_2130', 'hotel_2131', 'hotel_2132', 'hotel_2133', 'hotel_2134', 'hotel_2135', 'hotel_2136', 'hotel_2137', 'hotel_2138', 'hotel_2139', 'hotel_2140', 'hotel_2141', 'hotel_2142', 'hotel_2143', 'hotel_2144', 'hotel_2145', 'hotel_2146', 'hotel_2147', 'hotel_2148', 'hotel_2149', 'hotel_2150', 'hotel_2151', 'hotel_2152', 'hotel_2153', 'hotel_2154', 'hotel_2155', 'hotel_2156', 'hotel_2157', 'hotel_2158', 'hotel_2159', 'hotel_2160', 'hotel_2161', 'hotel_2162', 'hotel_2163', 'hotel_2164', 'hotel_2165', 'hotel_2166', 'hotel_2167', 'hotel_2168', 'hotel_2169', 'hotel_2170', 'hotel_2171', 'hotel_2172', 'hotel_2173', 'hotel_2174', 'hotel_2175', 'hotel_2176', 'hotel_2177', 'hotel_2178', 'hotel_2179', 'hotel_2180', 'hotel_2181', 'hotel_2182', 'hotel_2183', 'hotel_2184', 'hotel_2185', 'hotel_2186', 'hotel_2187', 'hotel_2188', 'hotel_2189', 'hotel_2190', 'hotel_2191', 'hotel_2192', 'hotel_2193', 'hotel_2194', 'hotel_2195', 'hotel_2196', 'hotel_2197', 'hotel_2198', 'hotel_2199', 'hotel_2200', 'hotel_2201', 'hotel_2202', 'hotel_2203', 'hotel_2204', 'hotel_2205', 'hotel_2206', 'hotel_2207', 'hotel_2208', 'hotel_2209', 'hotel_2210', 'hotel_2211'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

-- 1d. existing FR hotels, fill-only (never overwrites)
create temp table _hfill_fr (code text primary key, phone text, website_url text) on commit drop;
update public.hotels h set phone = f.phone, updated_at = now() from _hfill_fr f where h.hotel_code = f.code and f.phone is not null and h.phone is null;
update public.hotels h set website_url = f.website_url, updated_at = now() from _hfill_fr f where h.hotel_code = f.code and f.website_url is not null and h.website_url is null;

-- 2. links to French Key hotels, from MICHELIN's "Stay at the hotel" (78)
create temp table _links_fr (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
do $$
declare n int;
begin
  select count(*) into n from _links_fr l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code and h.country_code = 'FR')
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code and r.country_code = 'FR');
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
  select count(*) into n from _links_fr l join public.restaurants r on r.restaurant_code = l.restaurant_code
   where r.property_name is not null;
  if n <> 0 then raise exception '% linked restaurants carry a property_name -- review first', n; end if;
end $$;
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_fr l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN's 2026 French Keys, 25/38/157
do $$
declare n int;
begin
  select count(*) into n from public.hotels where country_code = 'FR' and michelin_keys = 3;
  if n <> 25 then raise exception 'expected 25 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'FR' and michelin_keys = 2;
  if n <> 38 then raise exception 'expected 38 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'FR' and michelin_keys = 1;
  if n <> 157 then raise exception 'expected 157 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'FR';
  if n <> 221 then raise exception 'expected 221 FR hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'FR' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% Key hotels without exactly one matching current Key row', n; end if;
  select count(*) into n from public.hotel_restaurants hr join public.restaurants r on r.id = hr.restaurant_id where r.country_code = 'FR';
  if n <> 83 then raise exception 'expected 83 FR restaurant hotel links, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'FR' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
end $$;

commit;
